# ================================================================ 30–31. Самое длинное совпадение
def ip2b(ip): return "".join(f"{int(o):08b}" for o in ip.split("."))
def bits(bid, dest, entries):
    """entries: [(подпись, сеть, префикс)]. Биты: m — совпал в пределах префикса, x — первое несовпадение, o — за пределами префикса."""
    db = ip2b(dest)
    def row(label, b, cls="", pref=None, tail=""):
        out = []
        for k, ch in enumerate(b):
            c = ""
            if pref is not None:
                if k < pref: c = "m" if ch == db[k] else "x"
                else: c = "o"
            sep = "." if k in (7, 15, 23) else ""
            out.append(f'<i class="{c}" style="--d:{k*35}ms">{ch}</i>{sep}')
        return f'<div class="br {cls}"><span class="bl2">{label}</span><span class="bn">{"".join(out)}</span><span>{tail}</span></div>'
    rows = [row(f"{dest}", db, "dst", None, "адрес назначения")]
    best = max((p for _, n, p in entries if ip2b(n)[:p] == db[:p]), default=-1)
    for k, (lab, net, p) in enumerate(entries, 1):
        ok = ip2b(net)[:p] == db[:p]
        res = ("самое длинное совпадение" if p == best else "совпадение короче") if ok else "несовпадение"
        rows.append(row(lab, ip2b(net), f"e{k} {'ok' if ok else 'no'} {'best' if p == best and ok else ''}", p, f'<b class="res">{res}</b>'))
    return f'<div class="bits pn" id="{bid}" data-s="1">{"".join(rows)}</div>'

